#include <bits/stdc++.h>
using namespace std;

struct Point {
    vector<long long> coords;

    Point(initializer_list<long long> c) : coords(c) {}

    long long computeLengthSq() const {
        long long total = 0;
        for (auto c : coords) {
            total += c * c;
        }
        return total;
    }

    long long scalarProduct(const Point& other) const {
        long long sum = 0;
        for (size_t i = 0; i < coords.size(); i++) {
            sum += coords[i] * other.coords[i];
        }
        return sum;
    }

    Point subtract(const Point& other) const {
        vector<long long> newCoords(coords.size());
        for (size_t i = 0; i < coords.size(); i++) {
            newCoords[i] = coords[i] - other.coords[i];
        }
        return Point{newCoords};
    }
};

bool verify(const vector<Point>& pts, int index) {
    const Point& current = pts[index];
    int totalPoints = (int)pts.size();
    for (int j = 0; j < totalPoints; j++) {
        if (j == index) continue;
        for (int k = 0; k < totalPoints; k++) {
            if (k == index || k == j) continue;
            Point vec1 = pts[j].subtract(current);
            Point vec2 = pts[k].subtract(current);
            if (vec1.scalarProduct(vec2) > 0) return false;
        }
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    if (n > 11) {
        cout << 0 << "\n";
        return 0;
    }
    vector<Point> points;
    for (int i = 0; i < n; i++) {
        vector<long long> coords(5);
        for (int j = 0; j < 5; j++) {
            cin >> coords[j];
        }
        points.emplace_back(coords);
    }
    vector<int> validIndices;
    for (int i = 0; i < n; i++) {
        if (verify(points, i)) {
            validIndices.push_back(i + 1);
        }
    }
    cout << validIndices.size() << "\n";
    for (int idx : validIndices) {
        cout << idx << "\n";
    }
    return 0;
}
